import boto3
from botocore.exceptions import ClientError, ParamValidationError

s3 = boto3.client("s3", region_name="us-east-1")
s3.create_bucket(Bucket="demo-errors-2026")

def read_config(key):
    try:
        return s3.get_object(Bucket="demo-errors-2026", Key=key)["Body"].read()
    except s3.exceptions.NoSuchKey:
        return b"{}"                                  # sensible default

print(read_config("missing.json"))                    # b'{}'

try:
    s3.head_object(Bucket="demo-errors-2026", Key="missing.json")
except ClientError as e:
    print(e.response["Error"]["Code"])                 # 404

try:
    s3.get_object(Bucket="demo-errors-2026")          # Key is required
except ParamValidationError as e:
    print("bad params:", type(e).__name__)             # bad params: ParamValidationError

