import boto3, pytest
from botocore.stub import Stubber
from moto import mock_aws
def save_report(s3, bucket, name, text):
    s3.put_object(Bucket=bucket, Key=f"reports/{name}", Body=text.encode())
    return f"s3://{bucket}/reports/{name}"
@pytest.fixture
def aws_env(monkeypatch):
    for k in ("AWS_ACCESS_KEY_ID", "AWS_SECRET_ACCESS_KEY"):
        monkeypatch.setenv(k, "testing")
    monkeypatch.setenv("AWS_DEFAULT_REGION", "us-east-1")

@mock_aws
def test_save_report_with_moto(aws_env):
    s3 = boto3.client("s3"); s3.create_bucket(Bucket="acme-reports")
    assert save_report(s3, "acme-reports", "q1.txt", "hi") == "s3://acme-reports/reports/q1.txt"
    assert s3.get_object(Bucket="acme-reports", Key="reports/q1.txt")["Body"].read() == b"hi"

def test_save_report_with_stubber(aws_env):
    s3 = boto3.client("s3")
    with Stubber(s3) as stub:
        stub.add_response("put_object", {}, {"Bucket": "acme-reports", "Key": "reports/x", "Body": b"y"})
        save_report(s3, "acme-reports", "x", "y")
        stub.assert_no_pending_responses()
